#!/usr/bin/env python3
"""case-scaleup-1111 step 4: PLAN.md from load/cands/emit pickles."""
import collections, pickle
G = '/local/home/mkhoshechin/Documents/github-jmc/'; SCR = '/local/home/mkhoshechin/tmp/case-scaleup-1111/'
X = pickle.load(open(SCR + 'cands.pkl', 'rb')); E = pickle.load(open(SCR + 'emit.pkl', 'rb'))
def f(x):
    try: return float(x)
    except: return 0.0
L = ['# Case-study scale-up 2026-11-11: plan (generated by daavar/scripts/case-scaleup-1111/md.py; estimates are planning numbers, R10)', '',
     'Brief: BRIEF.md. Rows: daavar/cluster/campaign/case-scaleup-1111/{brain,volta,pinky}-pool.rows(.tsv). One line per row: candidates.tsv.',
     'Scripts: load.py (inputs), gen.py (next sizes, estimates), emit.py (feasibility, groups, class, priority, rows), md.py (this file).', '']
c = collections.Counter((x[1], x[4]) for x in E['cand'])
L += ['## Counts (rows per host class and priority)', '', '| class | P1 | P2 | P3 |', '|---|---|---|---|']
for k in ('brain', 'volta', 'pinky'): L.append(f'| {k} | {c[(k,1)]} | {c[(k,2)]} | {c[(k,3)]} |')
L += ['', '## Assumptions', '',
 '1. Pair = an Offline merge join (`*.m`, prefixes C3J/XJ1/XJ2/XT1/XT2/XC1/XC2) of the case-study directories of the brief; C1/C2 (Online/Nested) rows ignored. Java-vs-Java (jimpl-jimpl) pairs are kept (unlike scaleup-1110), priority by the rules below.',
 '2. Measured size = a join with a brain-data record stop_reason ok. Next size = +1 (and +2 when the whole chain of the +2 step is estimated <= 12 h on a brain node) on one size axis of a maximal measured size. Axes: raft-rs/omnipaxos third argument structural (grid-axes.tsv); ZooKeeper `<e> <late>`: late is a switch, only e grows; crdb n in {1,2}, 0<=p<=n, m in {1,2}, a>=1, not (n=1,p=0) (cockroach/INTERFACE.md); ScalarDB k in {1,2} (scalardb/INTERFACE.md); craq/cassandra/chainpaxos/swiftpaxos/pineapple q>=1, bk e>=1.',
 '3. Exactly new: the join instance (words sorted, numbers in order, tier/rerun suffixes dropped) is in no rows file, no brain-data record and not running/pending CASE. Stale rows-file entries without a record also block a size (strict reading of the brief); see the notes.',
 '4. Blocked: an export of the pair whose instance at a size <= the candidate (coordinate by coordinate) hit a limit (timeout, memory, killed, jmc cap) or is a running/pending CASE row (wait for it).',
 '5. Every export a proposed join reads is proposed again under a fresh id in the same group (re-export on the join host), also when it was measured elsewhere; the reason says re-export. Importing an existing export.jsonl would save that time but is a manual step.',
 '6. Cost: export time at C = its brain-equivalent time at P x g, g = time ratio of the closest measured step of the same export along the same axis (the step ending at P preferred; accelerating growth multiplies g by the ratio of ratios; fallback: the largest step ratio of another export of the same directory family; times floored at 1 s). Memory: TraceForge M(P) x min(g, memory ratio of the step); JMC M(P) x g^0.6 when M(P) < 500 MB. Join = join time at P x the largest g of its exports. Time measured on volta/pinky counts half on a brain; volta/pinky estimates are brain x 2 (pinky30/32 not singled out).',
 '7. Class: the cheapest of pinky, volta, brain where the group peak is <= 70/180/230 GB and the worst row <= 24 h; else 24-36 h on volta/brain with priority 3; else left out.',
 '8. Priority (per row): 1 = Phase B (OmniPaxos, raft-rs, MicroRaft) or every measured size of the join conformed; else 3 = a join reading a JMC export (and exports of such groups); else 2. A JMC export inherits its group\'s best priority so that P1 joins are not starved by their exports. 24-36 h rows are 3.',
 '9. TiKV left out: its sizes are scenario switches, not a ladder (as scaleup-1110). raft-rs `reorder` left out: exploratory variant (exploratory-variants.tsv).',
 '10. Start of runs and wall-clock windows are not modelled; the coordinator places groups (a group must stay on one host).', '']
L += ['## Proposed joins (per study)', '']
by = collections.defaultdict(list)
for gid, cls, prio, cs in E['ginfo']:
    for cc in cs: by[cc['study']].append((gid, cls, cc))
for st in sorted(by):
    L.append(f'### {st}'); L.append('')
    L.append('| family | measured (size=verdict run id) | proposed | id | class | est h (row) | basis |'); L.append('|---|---|---|---|---|---|---|')
    for gid, cls, cc in sorted(by[st], key=lambda x: (x[2]['fam'], x[2]['C'])):
        vs = '; '.join(f"{','.join(map(str,n))}={v} `{i}`" for n, v, i in cc['verdicts'])
        L.append(f"| {cc['fam']} | {vs} | {','.join(map(str,cc['C']))} | `{cc['newid']}` | {cls} (g{gid}) | {cc['jt']/3600:.2f} + exports | {cc['jbasis']}; " + '; '.join(e['basis'] for e in cc['eplan']) + ' |')
    L.append('')
L += ['## Dropped as infeasible (estimate > 36 h or > 230 GB on a brain node)', '']
for cc, h, m in E['dropped']: L.append(f"- {cc['fam']} {','.join(map(str,cc['P']))} -> {','.join(map(str,cc['C']))}: worst row {h:.1f} h, peak {m:.1f} GB (" + '; '.join(e['basis'] for e in cc['eplan']) + ')')
L += ['', '## Families left out', '']
for fam, r in sorted(X['left'].items()): L.append(f'- {fam}: {r}')
L += ['', '## Notes per family (sizes not proposed and why)', '']
for fam, ns in sorted(X['notes'].items()): L.append(f'- {fam}: ' + ' | '.join(ns))
open(G + 'plan/eval2/case-scaleup-1111/PLAN.md', 'w').write('\n'.join(L) + '\n'); print(len(L), 'lines')
